"""AI alignment evaluation: monitor flag statistics over model transcripts."""


def monitor_flag_rate(events):
    """The share of transcripts whose ``flagged`` value is True."""
    if not events:
        return 0.0
    hits = sum(1 for event in events if event["flagged"] is True)
    return hits / len(events)


def pooled_flag_rate(groups):
    """The pooled flag rate across all transcripts in all groups."""
    events = [event for group in groups.values() for event in group]
    return monitor_flag_rate(events)


def flags_in_window(daily_counts, days):
    """Sum the last ``days`` entries of oldest-first daily counts."""
    if days <= 0:
        return 0
    return sum(daily_counts[-days:])


def flag_rate_by_group(groups):
    """Map each group name, in sorted order, to its flag rate."""
    return {
        name: monitor_flag_rate(groups[name]) if groups[name] else None
        for name in sorted(groups)
    }


def longest_flag_streak(daily_counts):
    """Return the longest run of consecutive positive daily counts."""
    best = current = 0
    for count in daily_counts:
        if count > 0:
            current += 1
            best = max(best, current)
        else:
            current = 0
    return best

"""Loading and aggregation helpers for monitor transcript logs."""


def parse_transcript_log(lines):
    """Parse comma-separated ``id,day,flagged`` log lines."""
    out = []
    for line_number, line in enumerate(lines, start=1):
        stripped = line.strip()
        if not stripped or stripped.startswith("#"):
            continue

        fields = [field.strip() for field in line.split(",")]
        if len(fields) != 3:
            raise ValueError(f"line {line_number}: expected exactly three fields")

        id_, day_text, flag_text = fields
        try:
            day = int(day_text)
        except ValueError as exc:
            raise ValueError(f"line {line_number}: day must be an integer") from exc

        if flag_text == "1":
            flagged = True
        elif flag_text == "0":
            flagged = False
        elif flag_text == "":
            flagged = None
        else:
            raise ValueError(f"line {line_number}: flagged must be 1, 0, or empty")

        out.append({"id": id_, "day": day, "flagged": flagged})
    return out


def dedupe_transcripts(events):
    """Keep the last transcript for each id and sort by day then id."""
    latest_by_id = {}
    for event in events:
        latest_by_id[event["id"]] = event
    return sorted(latest_by_id.values(), key=lambda event: (event["day"], event["id"]))


def daily_flag_counts(events, start_day, end_day):
    """Count flagged transcripts for each day in the inclusive range."""
    if end_day < start_day:
        return []

    counts = {day: 0 for day in range(start_day, end_day + 1)}
    for event in events:
        day = event["day"]
        if start_day <= day <= end_day and event["flagged"] is True:
            counts[day] += 1
    return [counts[day] for day in range(start_day, end_day + 1)]

import pytest

from safety_evals.loader import daily_flag_counts, dedupe_transcripts, parse_transcript_log
from safety_evals.metrics import (
    flag_rate_by_group,
    flags_in_window,
    longest_flag_streak,
    monitor_flag_rate,
    pooled_flag_rate,
)
from safety_evals.report import monitor_summary, top_flagged_groups


def test_monitor_flag_rate_basic():
    assert monitor_flag_rate([{"flagged": True}, {"flagged": False}]) == 0.5


def test_monitor_flag_rate_none_counts_as_not_flagged():
    assert monitor_flag_rate([{"flagged": True}, {"flagged": None}, {"flagged": False}]) == 1 / 3


def test_monitor_flag_rate_empty():
    assert monitor_flag_rate([]) == 0.0


def test_pooled_flag_rate_is_weighted_by_transcript_count():
    groups = {
        "large": [{"flagged": True}, {"flagged": False}, {"flagged": False}],
        "small": [{"flagged": True}],
        "empty": [],
    }
    assert pooled_flag_rate(groups) == 0.5
    assert pooled_flag_rate({"empty": []}) == 0.0


def test_flags_in_window_uses_last_days():
    assert flags_in_window([1, 2, 3], 2) == 5
    assert flags_in_window([1, 2, 3], 0) == 0
    assert flags_in_window([1, 2, 3], 10) == 6


def test_parse_transcript_log_fields_and_skipped_lines():
    assert parse_transcript_log([" # comment", "", " x, 2, ", "y,3,0"]) == [
        {"id": "x", "day": 2, "flagged": None},
        {"id": "y", "day": 3, "flagged": False},
    ]


@pytest.mark.parametrize("line", ["a,1", "a,not-a-day,1"])
def test_parse_transcript_log_errors_include_original_line_number(line):
    with pytest.raises(ValueError, match="line 2"):
        parse_transcript_log(["# ignored", line])


def test_parse_transcript_log_rejects_invalid_flag():
    with pytest.raises(ValueError, match="line 1"):
        parse_transcript_log(["a,1,true"])


def test_dedupe_transcripts_keeps_last_duplicate_id():
    old = {"id": "x", "day": 1, "flagged": True}
    replacement = {"id": "x", "day": 4, "flagged": False}
    other = {"id": "y", "day": 2, "flagged": True}
    assert dedupe_transcripts([old, other, replacement]) == [
        other,
        replacement,
    ]


def test_daily_flag_counts_inclusive_range():
    events = [
        {"day": 1, "flagged": True},
        {"day": 2, "flagged": None},
        {"day": 2, "flagged": True},
        {"day": 5, "flagged": True},
    ]
    assert daily_flag_counts(events, 2, 4) == [1, 0, 0]
    assert daily_flag_counts(events, 4, 3) == []


def test_monitor_summary():
    events = [
        {"id": "a", "day": 1, "flagged": True},
        {"id": "b", "day": 2, "flagged": False},
        {"id": "c", "day": 2, "flagged": True},
    ]
    summary = monitor_summary({"g": events, "empty": []}, 1)
    assert summary == {"rate": 0.667, "recent": 1, "groups": 1}
    assert monitor_summary({}, 1) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_top_flagged_groups_excludes_empty_and_breaks_ties_by_name():
    groups = {
        "z": [{"flagged": True}],
        "a": [{"flagged": True}],
        "empty": [],
    }
    assert top_flagged_groups(groups, 2) == ["a", "z"]


def test_flag_rate_by_group_sorts_keys_and_empty_is_none():
    assert flag_rate_by_group({"z": [], "b": [{"flagged": True}], "a": [{"flagged": False}]}) == {
        "a": 0.0,
        "b": 1.0,
        "z": None,
    }


def test_longest_flag_streak_counts_only_positive_values():
    assert longest_flag_streak([1, 2, 0, -1, 4, 5]) == 2
    assert longest_flag_streak([]) == 0
